import { test, expect } from '@playwright/test';

const FP_HEADER = { 'x-browser-fingerprint': 'qa-detail-spec-fp-001' };

test.describe('Post Detail & Admin Route Spec (Draft)', () => {
  test('API returns post detail, increments click count, and manages comments', async ({ request }) => {
    const postText = `Spec Detail Post ${Date.now()}`;
    const createRes = await request.post('/api/v1/posts', {
      headers: FP_HEADER,
      data: { content: postText },
    });
    expect(createRes.status()).toBe(201);
    const { id: postId } = await createRes.json();

    const detailRes = await request.get(`/api/v1/posts/${postId}`, { headers: FP_HEADER });
    expect(detailRes.status()).toBe(200);
    const detail = await detailRes.json();
    expect(detail.id).toBe(postId);
    expect(detail.content).toBe(postText);
    expect(Array.isArray(detail.images)).toBe(true);

    const clickRes = await request.post(`/api/v1/posts/${postId}/click`);
    expect(clickRes.status()).toBe(200);
    const clickBody = await clickRes.json();
    expect(clickBody.clicks_count).toBeGreaterThanOrEqual(1);

    const commentRes = await request.post(`/api/v1/posts/${postId}/comments`, {
      headers: FP_HEADER,
      data: { content: 'First detail comment' },
    });
    expect(commentRes.status()).toBe(201);
    const comment = await commentRes.json();
    expect(comment.post_id).toBe(postId);

    const listRes = await request.get(`/api/v1/posts/${postId}/comments`);
    expect(listRes.status()).toBe(200);
    const listBody = await listRes.json();
    expect(listBody.comments.some((c: { id: string }) => c.id === comment.id)).toBe(true);
  });

  test('User navigates from feed to post detail page and posts comment', async ({ page, request }) => {
    const postText = `Detail UI Post ${Date.now()}`;
    const createRes = await request.post('/api/v1/posts', {
      headers: FP_HEADER,
      data: { content: postText },
    });
    const { id: postId } = await createRes.json();

    await page.goto('/');
    const main = page.getByRole('main');
    const card = main.locator('article').filter({ hasText: postText }).first();
    await expect(card).toBeVisible();
    await expect(card.getByPlaceholder(/撰写评论|撰写回复/i)).toHaveCount(0);

    await card.getByRole('button', { name: /评论/i }).first().click();
    await expect(page).toHaveURL(new RegExp(`/posts/${postId}`));
    await expect(main.getByText(postText).first()).toBeVisible();

    const commentInput = main.getByPlaceholder(/撰写评论|撰写回复/i).first();
    await expect(commentInput).toBeVisible();
    const replyText = `Detail Reply ${Date.now()}`;
    await commentInput.fill(replyText);
    await main.getByRole('button', { name: /回复/i }).first().click();
    await expect(main.getByText(replyText).first()).toBeVisible();
  });

  test('/admin route loads admin login page without Not Found', async ({ page }) => {
    const response = await page.goto('/admin');
    expect(response?.status()).toBe(200);
    await expect(page.getByRole('heading', { name: /管理员登录/i })).toBeVisible();
    await expect(page.getByLabel(/管理员账号/i)).toBeVisible();
    await expect(page.getByLabel(/管理员密码/i)).toBeVisible();
  });
});
